$:set -euo pipefail
test -f AGENTS.md && cat AGENTS.md >/dev/null
if test -f README.md; then cat README.md >/dev/null; elif test -f README.json; then cat README.json >/dev/null; fi
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh api 'repos/BestNameYet/Terminals/contents/.devcontainer/devcontainer.json?ref=main' --jq .content | base64 --decode > /tmp/verify-codespace-public.json
node <<'NODE'
const fs=require('fs'),assert=require('assert');
const cfg=JSON.parse(fs.readFileSync('/tmp/verify-codespace-public.json','utf8'));
assert.deepStrictEqual(cfg.forwardPorts,[3000]);
assert.equal(cfg.postAttachCommand,'gh codespace ports visibility 3000:public -c "$CODESPACE_NAME"');
assert(cfg.postStartCommand.includes('PORT=3000'));
console.log('REMOTE_MAIN_PUBLIC_PORT_DEFAULT_VERIFIED=true');
console.log('POST_ATTACH_COMMAND='+cfg.postAttachCommand);
console.log('POST_START_COMMAND='+cfg.postStartCommand);
console.log('FORWARDED_PORT='+cfg.forwardPorts[0]);
NODE
gh api repos/BestNameYet/Terminals/commits/main --jq .sha
